mapper.select:
SELECT EXISTS (
    SELECT 1
      FROM tb_course_sessions
     WHERE course_id = #{courseId}
       AND status <> 'CANCELLED'
       AND NOT (
           status = 'COMPLETED'
           OR COALESCE(attendance_closes_at, ends_at) <= #{evaluatedAt}
       )
)

SELECT id, course_id, session_no, starts_at, ends_at, location,
       attendance_opens_at, attendance_closes_at, status, created_at, updated_at
  FROM tb_course_sessions
 WHERE course_id = #{courseId}
   AND session_no = #{sessionNo}

SELECT id, course_id, session_no, starts_at, ends_at, location, attendance_opens_at, attendance_closes_at, status, created_at, updated_at FROM tb_course_sessions WHERE course_id = #{criteria.courseId} ORDER BY
starts_at ends_at status created_at updated_at session_no
ASC DESC , id ASC LIMIT #{criteria.limit} OFFSET #{criteria.offset}

SELECT COUNT(*)
  FROM tb_course_sessions
 WHERE course_id = #{courseId}
